    28→
    29→/**
    30→ * 대전 게임 씬 — GameScene을 상속하여 코드 재사용
    31→ *
    32→ * BattleMatchScene에서 roomCode/userId를 받아 새 채널을 직접 생성합니다.
    33→ * (Supabase Realtime은 리스너 등록 → subscribe 순서 필수)
    34→ */
    35→export default class BattleGameScene extends GameScene {
    36→  private battleChannel: BattleChannel | null = null;
    37→  private roomCode: string = '';
    38→  private battleUserId: string = '';
    39→  private opponentId: string = '';
    40→  private opponentScore: number = 0;
    41→  private opponentScoreText!: Phaser.GameObjects.Text;
    42→  private scoreUpdateTimer!: Phaser.Time.TimerEvent;
    43→  private disconnectTimer: ReturnType<typeof setTimeout> | null = null;
    44→  private battleFinished: boolean = false;
