import type Phaser from 'phaser';
import { supabase } from '../utils/supabase';
import { getBattleLeaderboard, type BattleRecordEntry } from '../utils/battleLeaderboard';
import { getBattleTier } from '../utils/battleTier';
import BaseScene from './BaseScene';

export default class BattleLeaderboardScene extends BaseScene {
  private leaderboardEntries: BattleRecordEntry[] = [];
  private leaderboardTexts: Phaser.GameObjects.GameObject[] = [];
  private loadingText?: Phaser.GameObjects.Text;
  private currentUserRank: {
    rank: number;
    totalWins: number;
    winRate: number;
    ratingPoints: number;
  } | null = null;
  private currentUserId: string | null = null;

  constructor() {
    super('BattleLeaderboardScene');
  }

  preload() {
    if (!this.textures.exists('background2')) {
      this.load.image('background2', 'assets/backgrounds/background2.webp');
    }
  }

  create() {
    super.create();

    // 배경
    const bg = this.add.image(200, 300, 'background2');
    bg.setDisplaySize(400, 600);
    this.add.rectangle(200, 300, 400, 600, 0x000000, 0.75);

    // 타이틀
    this.add.text(200, 40, '⚔️ 배틀 전적', {
      fontSize: '28px',
      color: '#ff4444',
      fontStyle: 'bold',
      stroke: '#000',
      strokeThickness: 5,
    }).setOrigin(0.5);

    // 내 전적 영역 (로드 후 채워짐)
    this.loadingText = this.add.text(200, 300, '로딩 중...', {
      fontSize: '20px',
      color: '#ffffff',
      stroke: '#000',
      strokeThickness: 3,
    }).setOrigin(0.5);

    // 뒤로가기
    const backBtn = this.add.text(200, 565, '← 대전 모드', {
      fontSize: '18px',
      color: '#aaaaaa',
      stroke: '#000',
      strokeThickness: 3,
    }).setOrigin(0.5).setInteractive({ useHandCursor: true });
    backBtn.on('pointerover', () => backBtn.setColor('#ffffff'));
    backBtn.on('pointerout', () => backBtn.setColor('#aaaaaa'));
    backBtn.on('pointerdown', () => this.scene.start('BattleMatchScene'));

    // 유저 ID 백그라운드 조회
    supabase.auth.getUser().then(({ data }) => {
      if (data.user?.id) this.currentUserId = data.user.id;
    });

    this.loadLeaderboard();
  }

  private async loadLeaderboard() {
    try {
      const response = await getBattleLeaderboard(20);
      this.leaderboardEntries = response.leaderboard;
      this.currentUserRank = response.currentUserRank;

      if (this.loadingText) {
        this.loadingText.setVisible(false);
      }

      this.displayLeaderboard();
    } catch (error) {
      console.error('Failed to load battle leaderboard:', error);

      if (this.loadingText) {
        this.loadingText.setVisible(false);
      }

      this.add.text(200, 300, '전적을 불러올 수 없습니다\n나중에 다시 시도해주세요', {
        fontSize: '16px',
        color: '#ff6666',
        stroke: '#000',
        strokeThickness: 3,
        align: 'center',
      }).setOrigin(0.5);
    }
  }

  private displayLeaderboard() {
    // 기존 텍스트 제거
    for (const obj of this.leaderboardTexts) {
      if (obj.active) obj.destroy();
    }
    this.leaderboardTexts = [];

    // 내 전적 요약
    if (this.currentUserRank) {
      const myEntry = this.leaderboardEntries.find(e => e.userId === this.currentUserId);
      const wins = myEntry?.wins ?? 0;
      const losses = myEntry?.losses ?? 0;
      const disconnects = myEntry?.disconnects ?? 0;
      const { winRate, rank, ratingPoints } = this.currentUserRank;
      const myTier = getBattleTier(ratingPoints);

      const summaryText = this.add.text(
        200, 85,
        `${myTier.icon} ${myTier.name} | ${ratingPoints} RP | ${wins}승 ${disconnects}부 ${losses}패 | ${winRate}% (${rank}위)`,
        {
          fontSize: '12px',
          color: '#FFD700',
          stroke: '#000',
          strokeThickness: 3,
        },
      ).setOrigin(0.5);
      this.leaderboardTexts.push(summaryText);
    }

    // 구분선
    const divider = this.add.rectangle(200, 110, 360, 2, 0x555555);
    this.leaderboardTexts.push(divider);

    // 헤더
    const header = this.add.text(200, 128, '순위  이름   티어      RP    승률', {
      fontSize: '13px',
      color: '#ffff00',
      fontStyle: 'bold',
      fontFamily: 'monospace',
      stroke: '#000',
      strokeThickness: 3,
    }).setOrigin(0.5);
    this.leaderboardTexts.push(header);

    if (this.leaderboardEntries.length === 0) {
      const noData = this.add.text(200, 300, '아직 대전 기록이 없습니다\n첫 번째 플레이어가 되어보세요!', {
        fontSize: '16px',
        color: '#cccccc',
        stroke: '#000',
        strokeThickness: 3,
        align: 'center',
      }).setOrigin(0.5);
      this.leaderboardTexts.push(noData);
      return;
    }

    const startY = 155;
    const lineH = 31;

    this.leaderboardEntries.forEach((entry, index) => {
      const y = startY + index * lineH;
      const isMe = entry.userId === this.currentUserId;
      const tier = getBattleTier(entry.ratingPoints);

      // 현재 유저 행 하이라이트
      if (isMe) {
        const highlight = this.add.rectangle(200, y, 380, 28, 0x8B6914, 0.5);
        this.leaderboardTexts.push(highlight);
      }

      // 순위 색상
      let color = '#ffffff';
      if (entry.rank === 1) color = '#FFD700';
      else if (entry.rank === 2) color = '#C0C0C0';
      else if (entry.rank === 3) color = '#CD7F32';
      else if (isMe) color = '#FFD700';

      const rankStr = `${entry.rank}`.padStart(2, ' ');
      const nameStr = entry.userName.padEnd(5, ' ');
      const tierStr = `${tier.icon}${tier.name}`.padEnd(7, ' ');
      const rpStr = `${entry.ratingPoints}`.padStart(4, ' ');
      const rateStr = `${entry.winRate}%`.padStart(5, ' ');

      const text = this.add.text(
        200, y,
        `${rankStr}  ${nameStr}  ${tierStr}  ${rpStr}  ${rateStr}`,
        {
          fontSize: '13px',
          color,
          fontFamily: 'monospace',
          stroke: '#000',
          strokeThickness: 3,
        },
      ).setOrigin(0.5);
      this.leaderboardTexts.push(text);
    });
  }
}

-- rating_points 컬럼 추가 (기존 유저는 1000으로 초기화)
ALTER TABLE public.battle_records
  ADD COLUMN IF NOT EXISTS rating_points INTEGER NOT NULL DEFAULT 1000;

-- 기존 함수/뷰 교체
DROP FUNCTION IF EXISTS increment_battle_record(UUID, TEXT);
DROP FUNCTION IF EXISTS get_battle_rank(INTEGER);
DROP VIEW IF EXISTS public.battle_leaderboard_view;

-- 신규 통합 함수: upsert + RP 업데이트 + rank 반환
-- RETURNS TABLE 컬럼명이 테이블 컬럼명과 동일하면 SET 우변에서 모호성 발생 →
-- 현재 값을 변수로 먼저 읽고 계산한 뒤, 우변에는 변수만 사용하여 해결
CREATE OR REPLACE FUNCTION submit_battle_record(
  p_user_id     UUID,
  p_result      TEXT,        -- 'win' | 'lose' | 'disconnect'
  p_point_delta INTEGER      -- Edge Function에서 계산한 델타 (음수 가능)
)
RETURNS TABLE(rating_points INTEGER, wins INTEGER, losses INTEGER, disconnects INTEGER, rank BIGINT)
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  v_rp   INT;
  v_w    INT;
  v_l    INT;
  v_d    INT;
  v_rank BIGINT;
BEGIN
  INSERT INTO public.battle_records (user_id) VALUES (p_user_id)
  ON CONFLICT (user_id) DO NOTHING;

  -- 현재 값을 변수로 읽기 (테이블 alias로 명시적 참조)
  SELECT br.rating_points, br.wins, br.losses, br.disconnects
    INTO v_rp, v_w, v_l, v_d
    FROM public.battle_records br WHERE br.user_id = p_user_id;

  -- 새 값 계산 (모두 변수 연산 → 컬럼명 모호성 없음)
  v_rp := GREATEST(0, COALESCE(v_rp, 1000) + p_point_delta);
  v_w  := COALESCE(v_w, 0) + CASE WHEN p_result = 'win'        THEN 1 ELSE 0 END;
  v_l  := COALESCE(v_l, 0) + CASE WHEN p_result = 'lose'       THEN 1 ELSE 0 END;
  v_d  := COALESCE(v_d, 0) + CASE WHEN p_result = 'disconnect' THEN 1 ELSE 0 END;

  -- SET 우변 전부 변수 → 모호성 제거
  UPDATE public.battle_records SET
    rating_points = v_rp,
    wins          = v_w,
    losses        = v_l,
    disconnects   = v_d,
    updated_at    = NOW()
  WHERE user_id = p_user_id;

  -- rank 계산 (테이블 alias로 컬럼 명시)
  SELECT COUNT(*) + 1 INTO v_rank
    FROM public.battle_records br2 WHERE br2.rating_points > v_rp;

  RETURN QUERY SELECT v_rp, v_w, v_l, v_d, v_rank;
END; $$;

REVOKE ALL ON FUNCTION submit_battle_record FROM PUBLIC;
GRANT EXECUTE ON FUNCTION submit_battle_record TO service_role;

-- 랭킹 뷰 (rating_points DESC 정렬)
CREATE OR REPLACE VIEW public.battle_leaderboard_view AS
SELECT
  br.user_id,
  br.rating_points,
  br.wins,
  br.losses,
  br.disconnects,
  CASE
    WHEN (br.wins + br.losses + br.disconnects) = 0 THEN 0.0
    ELSE ROUND(
      (br.wins + br.disconnects)::NUMERIC
      / (br.wins + br.losses + br.disconnects)::NUMERIC * 100,
      1
    )
  END AS win_rate,
  p.initials
FROM public.battle_records br
JOIN public.profiles p ON p.id = br.user_id
ORDER BY br.rating_points DESC;

GRANT SELECT ON public.battle_leaderboard_view TO anon, authenticated;

-- 현재 유저 rank 계산용 함수 (RP 기반)
CREATE OR REPLACE FUNCTION get_battle_rank_by_rp(p_rp INTEGER)
RETURNS BIGINT LANGUAGE sql STABLE AS $$
  SELECT COUNT(*) FROM public.battle_records WHERE rating_points > p_rp;
$$;
GRANT EXECUTE ON FUNCTION get_battle_rank_by_rp TO anon, authenticated, service_role;

