     1→import { type RealtimeChannel } from '@supabase/supabase-js';
     2→import { supabase } from './supabase';
     3→import {
     4→  BattleEvent,
     5→  type ReadyPayload,
     6→  type GameStartPayload,
     7→  type SendPoopPayload,
     8→  type ScoreUpdatePayload,
     9→  type GameOverPayload,
    10→} from '../types/BattleTypes';
    11→
    12→type BattlePayloadMap = {
    13→  [BattleEvent.READY]: ReadyPayload;
    14→  [BattleEvent.GAME_START]: GameStartPayload;
    15→  [BattleEvent.SEND_POOP]: SendPoopPayload;
    16→  [BattleEvent.SCORE_UPDATE]: ScoreUpdatePayload;
    17→  [BattleEvent.GAME_OVER]: GameOverPayload;
    18→};
    19→
    20→/**
    21→ * Supabase Realtime Broadcast 채널 래퍼
    22→ *
    23→ * ⚠️ Supabase Realtime은 `.on()` 리스너를 `.subscribe()` 전에 등록해야 합니다.
    24→ * 따라서 채널 생성(createRoom/joinRoom) → 리스너 등록(onEvent 등) → 구독(subscribe) 순서로 호출하세요.
    25→ */
    26→export class BattleChannel {
    27→  private channel: RealtimeChannel | null = null;
    28→  private roomCode: string = '';
    29→  private userId: string = '';
    30→
    31→  /** 4자리 랜덤 방 코드 생성 */
    32→  static generateRoomCode(): string {
    33→    const chars = 'REDACTED'; // 혼동 문자(I,O,0,1) 제외
    34→    let code = '';
    35→    for (let i = 0; i < 4; i++) {
    36→      code += chars[Math.floor(Math.random() * chars.length)];
    37→    }
    38→    return code;
    39→  }
    40→
    41→  /** 방 생성 (호스트) — 채널만 생성, subscribe는 별도 호출 */
    42→  createRoom(code: string, userId: string): void {
    43→    this.roomCode = code;
    44→    this.userId = userId;
    45→    this.createChannel('battle-room');
    46→  }
    47→
    48→  /** 방 참가 (게스트) — 채널만 생성, subscribe는 별도 호출 */
    49→  joinRoom(code: string, userId: string): void {
    50→    this.roomCode = code;
    51→    this.userId = userId;
    52→    this.createChannel('battle-room');
    53→  }
    54→
    55→  /**
    56→   * 게임 채널 참가 (BattleGameScene 전용)
    57→   * 매칭 채널(battle-room:)과 다른 토픽을 사용하여 Presence 이벤트 혼선 방지
    58→   * — BattleMatchScene 채널 제거 시 발생하는 spurious presence leave가
    59→   *   BattleGameScene에 전달되지 않도록 격리
    60→   */
    61→  joinGame(code: string, userId: string): void {
    62→    this.roomCode = code;
    63→    this.userId = userId;
    64→    this.createChannel('battle-game');
    65→  }
    66→
    67→  /** 채널 객체만 생성 (구독하지 않음) */
    68→  private createChannel(topicPrefix: string): void {
    69→    this.channel = supabase.channel(`${topicPrefix}:${this.roomCode}`, {
    70→      config: {
    71→        broadcast: { self: false },
    72→        presence: { key: this.userId },
    73→      },
    74→    });
    75→  }
    76→
    77→  /**
    78→   * 리스너 등록 완료 후 호출 — 실제 WebSocket 구독 시작 + Presence track
    79→   * 반드시 onEvent/onPresenceJoin/onPresenceLeave 등록 후에 호출하세요.
    80→   */
    81→  async subscribe(): Promise<void> {
    82→    if (!this.channel) return;
    83→    return new Promise((resolve) => {
    84→      // 10초 타임아웃 — SUBSCRIBED가 오지 않아도 진행 (채널 불안정 시 stuck 방지)
    85→      const timeout = setTimeout(() => {
    86→        console.warn('[BattleChannel] subscribe timeout — forcing channelReady');
    87→        resolve();
    88→      }, 10000);
    89→
    90→      this.channel!.subscribe(async (status) => {
    91→        if (status === 'SUBSCRIBED') {
    92→          clearTimeout(timeout);
    93→          await this.channel!.track({ userId: this.userId, joinedAt: Date.now() });
    94→          resolve();
    95→        } else if (status === 'CHANNEL_ERROR' || status === 'TIMED_OUT' || status === 'CLOSED') {
    96→          console.warn('[BattleChannel] subscribe failed with status:', status);
    97→          clearTimeout(timeout);
    98→          resolve(); // 에러여도 강제 진행 (무한 대기 방지)
    99→        }
   100→      });
   101→    });
   102→  }
   103→
   104→  /** Broadcast 이벤트 리스너 등록 (subscribe 전에 호출) */
   105→  onEvent<E extends BattleEvent>(event: E, callback: (payload: BattlePayloadMap[E]) => void): void {
   106→    if (!this.channel) return;
   107→    this.channel.on('broadcast', { event }, (msg) => {
   108→      callback(msg.payload as BattlePayloadMap[E]);
   109→    });
   110→  }
   111→
   112→  /** Presence 동기화 — 상대 참가 감지 (subscribe 전에 호출) */
   113→  onPresenceJoin(callback: (userId: string) => void): void {
   114→    if (!this.channel) return;
   115→    this.channel.on('presence', { event: 'join' }, ({ newPresences }) => {
   116→      for (const p of newPresences) {
   117→        const uid = (p as Record<string, unknown>).userId as string;
   118→        if (uid && uid !== this.userId) {
   119→          callback(uid);
   120→        }
   121→      }
   122→    });
   123→  }
   124→
   125→  /** Presence 동기화 — 상대 이탈 감지 (subscribe 전에 호출) */
   126→  onPresenceLeave(callback: (userId: string) => void): void {
   127→    if (!this.channel) return;
   128→    this.channel.on('presence', { event: 'leave' }, ({ leftPresences }) => {
   129→      for (const p of leftPresences) {
   130→        const uid = (p as Record<string, unknown>).userId as string;
   131→        if (uid && uid !== this.userId) {
   132→          callback(uid);
   133→        }
   134→      }
   135→    });
   136→  }
   137→
   138→  /** 현재 Presence 상태에서 상대방이 있는지 확인 */
   139→  getOpponentPresence(): string | null {
