+function formatSurvivalTime(ms: number): string {
+  const totalSec = ms / 1000;
+  if (totalSec < 60) {
+    return `${totalSec.toFixed(1)}초`;
+  }
+  const min = Math.floor(totalSec / 60);
+  const sec = (totalSec % 60).toFixed(1).padStart(4, '0');
+  return `${min}:${sec}`;
+}
