    96→    } else {
    97→      this.userId = `anon-${Date.now()}`;
    98→      supabase.auth.getUser().then(({ data }) => {
    99→        if (data.user?.id) this.userId = data.user.id;
   100→      });
   101→    }
   102→
   103→    // 초기 상태: 재도전이면 자동 참가, 아니면 메뉴
   104→    if (this.autoRematch) {
   105→      this.handleAutoRematch(this.autoRematch.code, this.autoRematch.isHost);
   106→    } else {
   107→      this.showMenu();
   108→    }
