   438→  // ─── 채널 이벤트 ───────────────────────────────────────────────
   439→
   440→  private setupChannelListeners() {
   441→    if (!this.battleChannel) return;
   442→
   443→    // Presence join — 호스트일 때 상대 입장 감지 → 준비완료 버튼 표시
   444→    // (readyButtonShown 가드로 중복 렌더링 방지)
   445→    this.battleChannel.onPresenceJoin(() => {
   446→      if (this.isHost) this.showReadyButton();
   447→    });
   448→
   449→    this.battleChannel.onPresenceLeave(() => {
   450→      this.opponentReady = false;
   451→      this.ui(this.add.text(200, 420, '⚠️ 상대방이 나갔습니다', {
   452→        fontSize: '16px', color: '#ff4444',
   453→        stroke: '#000', strokeThickness: 3,
   454→      }).setOrigin(0.5));
   455→    });
   456→
   457→    // READY 수신 = 상대 준비 완료
   458→    // 호스트가 presence join보다 READY를 먼저 받는 경우(레이스) → ready 버튼을 보여줘야 진행 가능
   459→    this.battleChannel.onEvent(BattleEvent.READY, (payload: ReadyPayload) => {
   460→      this.opponentReady = true;
   461→      if (payload.userId) this.opponentUserId = payload.userId;
   462→      if (this.isHost) this.showReadyButton();
   463→      this.checkBothReady();
   464→    });
   465→
   466→    this.battleChannel.onEvent(BattleEvent.GAME_START, () => {
   467→      if (!this.countdownStarted) {
   468→        this.countdownStarted = true;
   469→        this.showCountdown();
   470→      }
   471→    });
   472→  }
   473→
   474→  /** ready 전송 (준비완료 버튼에서 호출) */
   475→  private doSendReady() {
   476→    if (!this.battleChannel || this.myReady) return;
   477→    this.myReady = true;
   478→    const charId = getSafeSelectedCharacter();
   479→    this.battleChannel.sendReady(charId);
   480→
   481→    // UI 갱신: 상대 대기 화면
   482→    this.clearUI();
   483→    this.ui(this.add.text(200, 270, '✅ 준비 완료!', {
   484→      fontSize: '24px', color: '#00ff00', fontStyle: 'bold',
   485→      stroke: '#000', strokeThickness: 4,
   486→    }).setOrigin(0.5));
   487→    this.ui(this.add.text(200, 320, '상대를 기다리는 중...', {
   488→      fontSize: '16px', color: '#ffffff',
   489→      stroke: '#000', strokeThickness: 3,
   490→    }).setOrigin(0.5));
   491→
   492→    // READY를 주기적으로 재전송 — 네트워크/타이밍 이슈로 상대가 수신 못했을 때 대비
   493→    // setInterval 사용 (Phaser 타이머는 백그라운드 탭에서 멈추므로)
   494→    this.clearReadyRetry();
   495→    this.readyRetryTimer = setInterval(() => {
   496→      if (this.countdownStarted || !this.battleChannel) {
   497→        this.clearReadyRetry();
   498→        return;
   499→      }
   500→      this.battleChannel.sendReady(charId);
   501→    }, 1500);
   502→
   503→    this.checkBothReady();
   504→  }
   505→
   506→  private clearReadyRetry() {
   507→    if (this.readyRetryTimer) {
   508→      clearInterval(this.readyRetryTimer);
   509→      this.readyRetryTimer = null;
   510→    }
   511→  }
   512→
   513→  private checkBothReady() {
   514→    if (this.myReady && this.opponentReady && this.isHost && !this.countdownStarted) {
   515→      this.countdownStarted = true;
   516→      this.battleChannel?.sendGameStart(Date.now());
   517→      this.showCountdown();
   518→    }
   519→  }
   520→
   521→  // ─── 상태 4: 카운트다운 ────────────────────────────────────────
   522→
   523→  private showCountdown() {
   524→    this.clearUI();
   525→
   526→    let count = 3;
   527→    const countText = this.ui(this.add.text(200, 280, `${count}`, {
   528→      fontSize: '90px', color: '#ff4444', fontStyle: 'bold',
   529→      stroke: '#000', strokeThickness: 8,
   530→    }).setOrigin(0.5));
   531→
   532→    const timer = this.time.addEvent({
   533→      delay: 1000,
   534→      callback: () => {
   535→        count--;
   536→        if (count > 0) {
   537→          (countText as Phaser.GameObjects.Text).setText(`${count}`);
   538→        } else {
   539→          (countText as Phaser.GameObjects.Text).setText('GO!');
   540→          (countText as Phaser.GameObjects.Text).setColor('#00ff00');
   541→          timer.remove();
   542→          this.time.delayedCall(500, () => this.goToBattle());
   543→        }
   544→      },
   545→      repeat: 2,
   546→    });
   547→  }
   548→
   549→  // ─── 씬 전환 ──────────────────────────────────────────────────
   550→
   551→  private goToBattle() {
   552→    this.clearReadyRetry();
   553→    const roomCode = this.battleChannel?.code ?? '';
   554→    const userId = this.userId;
   555→
   556→    // 동기식 채널 제거: supabase.channel()이 싱글턴이므로
   557→    // removeChannel을 먼저 호출해야 BattleGameScene에서 새 채널 생성 가능
   558→    if (this.battleChannel) {
   559→      this.battleChannel.destroyImmediate();
   560→      this.battleChannel = null;
