      this.battleChannel.sendPoop(1);

      const sendText = this.add.text(200, 150, '💩→ 상대에게 전송!', {
        fontSize: '16px',
        color: '#ff4444',
        fontStyle: 'bold',
        stroke: '#000',
        strokeThickness: 3,
      }).setOrigin(0.5).setDepth(200);
      this.tweens.add({
        targets: sendText,
