    // RESULT_LEAVE: 상대가 의도적으로 내비게이션 시 즉시 알림 (Broadcast 기반)
    this.rematchChannel.onEvent(BattleEvent.RESULT_LEAVE, () => {
      this.onOpponentLeft();
    });

    // Presence leave: 브라우저 종료 등 예기치 않은 이탈 fallback
    this.rematchChannel.onPresenceLeave(() => {
      this.onOpponentLeft();
