// ─── 랭크 매칭 ─────────────────────────────────────────────────

private async startRankedMatchmaking() {
  if (this.isMatchmaking || this.battleChannel) return;
  this.isMatchmaking = true;

  try {
    // 인증 보장 (익명 로그인 포함)
    this.userId = await getAuthUserId();
  } catch {
    this.isMatchmaking = false;
    return;
  }

  this.showRankedWaiting();

  let result: MatchResult;
  try {
    result = await findOrCreateMatch(this.userId);
  } catch {
    this.isMatchmaking = false;
    this.showMenu();
    return;
  }

  if (result.status === 'matched') {
    this.onRankedMatchFound(result);
    return;
  }

  // 대기 중 — 2초마다 폴링
  this.rankMatchPollTimer = setInterval(async () => {
    try {
      const poll = await pollMatchStatus(this.userId);
      if (poll?.status === 'matched') {
        this.clearRankedPoll();
        this.onRankedMatchFound(poll);
      }
    } catch {
      // 네트워크 오류 시 계속 재시도
    }
  }, 2000);
}

private showRankedWaiting() {
  this.clearUI();

  this.ui(this.add.text(200, 230, '🎖️ 랭크 매칭 중...', {
    fontSize: '22px', color: '#FFD700', fontStyle: 'bold',
    stroke: '#000', strokeThickness: 4,
  }).setOrigin(0.5));

  this.ui(this.add.text(200, 278, '상대를 찾고 있습니다', {
    fontSize: '15px', color: '#aaaaaa',
    stroke: '#000', strokeThickness: 3,
  }).setOrigin(0.5));

  let elapsed = 0;
  const elapsedText = this.ui(this.add.text(200, 310, '0초', {
    fontSize: '14px', color: '#888888',
    stroke: '#000', strokeThickness: 2,
  }).setOrigin(0.5));

  this.uiTimers.push(this.time.addEvent({
    delay: 1000, loop: true,
    callback: () => {
      elapsed++;
      if (!elapsedText.active) return;
      const m = Math.floor(elapsed / 60);
      const s = elapsed % 60;
      (elapsedText as Phaser.GameObjects.Text).setText(
        m > 0 ? `${m}:${s.toString().padStart(2, '0')}` : `${s}초`,
      );
    },
  }));

  // 취소 버튼
  const cancelBtn = this.ui(this.add.rectangle(200, 400, 200, 50, 0x555555));
  cancelBtn.setStrokeStyle(2, 0xffffff);
  this.ui(this.add.text(200, 400, '취소', {
    fontSize: '18px', color: '#ffffff',
  }).setOrigin(0.5));
  cancelBtn.setInteractive({ useHandCursor: true });
  cancelBtn.on('pointerover', () => cancelBtn.setAlpha(0.8));
  cancelBtn.on('pointerout', () => cancelBtn.setAlpha(1));
  cancelBtn.on('pointerdown', () => this.cancelRankedMatchmaking());

