  this.ownedChars = getOwnedCharacters();
  const currentId = getSafeSelectedCharacter();
  this.charPickIdx = Math.max(0, this.ownedChars.indexOf(currentId));

  const def = getCharacterDef(this.ownedChars[this.charPickIdx]);

