      fontSize: '14px', color: '#aaaaaa', stroke: '#000', strokeThickness: 3,
    }).setOrigin(0.5));
    this.ui(this.add.text(200, 198, 'VS', {
      fontSize: '20px', color: '#ff4444', fontStyle: 'bold',
      stroke: '#000', strokeThickness: 4,
    }).setOrigin(0.5));
    this.ui(this.add.text(304, 198, '상대', {
      fontSize: '14px', color: '#aaaaaa', stroke: '#000', strokeThickness: 3,
    }).setOrigin(0.5));

    // ── 내 캐릭터 (왼쪽) ─────────────────────────────────────────
    this.ui(this.add.rectangle(96, 258, 90, 100, 0x000033, 0.7)
