     1→import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
     2→
     3→const corsHeaders = {
     4→  'Access-Control-Allow-Origin': '*',
     5→  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
     6→};
     7→
     8→const VALID_RESULTS = ['win', 'lose', 'disconnect'] as const;
     9→type BattleResultValue = typeof VALID_RESULTS[number];
    10→
    11→// ── 티어 계산 (battleTier.ts 로직 인라인 — Deno에서 로컬 TS 공유 불가) ──
    12→
    13→interface TierDef {
    14→  minRp: number;
    15→  maxRp: number;
    16→}
    17→
    18→const TIERS: TierDef[] = [
    19→  { minRp: 0,    maxRp: 499 },
    20→  { minRp: 500,  maxRp: 999 },
    21→  { minRp: 1000, maxRp: 1499 },
    22→  { minRp: 1500, maxRp: 1999 },
    23→  { minRp: 2000, maxRp: Infinity },
    24→];
    25→
    26→const TIER_NAMES = ['알파', '베타', '레거시', '마스터', '갓'];
    27→const TIER_ICONS = ['🔴', '🟠', '🟡', '💎', '👑'];
    28→
    29→function getTierIndex(rp: number): number {
    30→  for (let i = TIERS.length - 1; i >= 0; i--) {
    31→    if (rp >= TIERS[i].minRp) return i;
    32→  }
    33→  return 0;
    34→}
    35→
    36→function calcPointDelta(
    37→  result: BattleResultValue,
    38→  myRp: number,
    39→  opponentRp: number,
    40→): number {
    41→  if (result === 'disconnect') return 20;
    42→
    43→  const tierDiff = getTierIndex(opponentRp) - getTierIndex(myRp);
    44→
    45→  if (result === 'win') {
    46→    if (tierDiff >= 2)   return 35;
    47→    if (tierDiff === 1)  return 30;
    48→    if (tierDiff === 0)  return 25;
    49→    if (tierDiff === -1) return 20;
    50→    return 15;
    51→  } else {
    52→    if (tierDiff >= 2)   return -10;
    53→    if (tierDiff === 1)  return -15;
    54→    if (tierDiff === 0)  return -20;
    55→    if (tierDiff === -1) return -25;
    56→    return -30;
    57→  }
    58→}
    59→
    60→// ── 메인 핸들러 ──
    61→
    62→Deno.serve(async (req: Request) => {
    63→  if (req.method === 'OPTIONS') {
    64→    return new Response('ok', { headers: corsHeaders });
    65→  }
    66→
    67→  try {
    68→    const { result, opponentId } = await req.json();
    69→
    70→    // 입력 검증
    71→    if (!VALID_RESULTS.includes(result)) {
    72→      return new Response(
    73→        JSON.stringify({ error: 'Invalid result: must be win, lose, or disconnect' }),
    74→        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
    75→      );
    76→    }
    77→
    78→    // JWT 인증 (필수)
    79→    const authHeader = req.headers.get('Authorization');
    80→    if (!authHeader) {
    81→      return new Response(
    82→        JSON.stringify({ error: 'Missing authorization header' }),
    83→        { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
    84→      );
    85→    }
    86→
