   287→  private async startRankedMatchmaking() {
   288→    if (this.isMatchmaking || this.battleChannel) return;
   289→    this.isMatchmaking = true;
   290→
   291→    try {
   292→      // 인증 보장 (익명 로그인 포함)
   293→      this.userId = await getAuthUserId();
   294→    } catch {
   295→      this.isMatchmaking = false;
   296→      return;
   297→    }
   298→
   299→    this.showRankedWaiting();
   300→
   301→    let result: MatchResult;
   302→    try {
   303→      result = await findOrCreateMatch(this.userId);
   304→    } catch {
   305→      this.isMatchmaking = false;
   306→      this.showMenu();
   307→      return;
   308→    }
   309→
   310→    if (result.status === 'matched') {
   311→      this.onRankedMatchFound(result);
   312→      return;
   313→    }
   314→
   315→    // 대기 중 — 2초마다 폴링
   316→    this.rankMatchPollTimer = setInterval(async () => {
   317→      try {
   318→        const poll = await pollMatchStatus(this.userId);
   319→        if (poll?.status === 'matched') {
   320→          this.clearRankedPoll();
   321→          this.onRankedMatchFound(poll);
   322→        }
   323→      } catch {
   324→        // 네트워크 오류 시 계속 재시도
   325→      }
   326→    }, 2000);
   327→  }
