   387→  private async onRankedMatchFound(match: MatchResult) {
   388→    if (!match.roomCode || match.isHost === null || !match.opponentId) return;
   389→    this.isRanked = true;
   390→    this.isMatchmaking = false;
   391→
   392→    // 대기열에서 제거 (fire-and-forget)
   393→    cancelMatchmaking(this.userId).catch(() => {});
   394→
   395→    await this.handleRankedJoin(match.roomCode, match.isHost, match.opponentId);
   396→  }
