   408→
   409→    this.battleChannel = new BattleChannel();
   410→    if (asHost) {
   411→      this.battleChannel.createRoom(roomCode, this.userId);
   412→    } else {
   413→      this.battleChannel.joinRoom(roomCode, this.userId);
