   664→      this.opponentCharPlaceholder = this.ui(this.add.text(304, 280, '?', {
   665→        fontSize: '42px', color: '#555555', stroke: '#000', strokeThickness: 3,
   666→      }).setOrigin(0.5));
   667→      this.opponentCharNameTxt = this.ui(this.add.text(304, 342, '대기 중...', {
   668→        fontSize: '14px', color: '#666666', stroke: '#000', strokeThickness: 2,
   669→      }).setOrigin(0.5));
   670→      this.opponentCharGradeTxt = this.ui(this.add.text(304, 362, '', {
   671→        fontSize: '13px', color: '#666666',
   672→      }).setOrigin(0.5));
   673→    }
   674→
   675→    // ── 준비 버튼 ─────────────────────────────────────────────────
   676→    this.ui(this.add.text(200, 400, '캐릭터를 확인하고 준비하세요', {
   677→      fontSize: '13px', color: '#bbbbbb', stroke: '#000', strokeThickness: 2,
   678→    }).setOrigin(0.5));
   679→
   680→    const readyBtn = this.ui(this.add.rectangle(200, 440, 270, 64, 0x1e8449));
   681→    readyBtn.setStrokeStyle(3, 0xffffff);
   682→    this.ui(this.add.text(200, 440, '✅ 준비완료', {
   683→      fontSize: '24px', color: '#ffffff', fontStyle: 'bold',
   684→      stroke: '#000', strokeThickness: 4,
   685→    }).setOrigin(0.5));
   686→    readyBtn.setInteractive({ useHandCursor: true });
   687→    readyBtn.on('pointerover', () => readyBtn.setFillStyle(0x27ae60));
   688→    readyBtn.on('pointerout', () => readyBtn.setFillStyle(0x1e8449));
   689→    readyBtn.on('pointerdown', () => this.doSendReady());
   690→  }
   691→
   692→  /** 상대 캐릭터 정보 표시 (READY 수신 시 또는 ready 화면 진입 시 호출) */
   693→  private showOpponentCharacter(charId: string) {
   694→    try {
   695→      const def = getCharacterDef(charId);
   696→      if (this.textures.exists(def.imageKey)) {
   697→        this.updateOpponentCharDisplay(def);
   698→      } else {
   699→        this.load.image(def.imageKey, def.imagePath);
   700→        this.load.once('complete', () => {
   701→          if (this.scene.isActive()) this.updateOpponentCharDisplay(def);
   702→        });
   703→        this.load.start();
   704→      }
   705→    } catch {
   706→      // 알 수 없는 캐릭터 ID 무시
   707→    }
   708→  }
   709→
   710→  private updateOpponentCharDisplay(def: CharacterDef) {
   711→    // 플레이스홀더 제거
   712→    if (this.opponentCharPlaceholder?.active) {
   713→      this.opponentCharPlaceholder.destroy();
   714→      this.opponentCharPlaceholder = null;
   715→    }
   716→    // 이미지
   717→    if (this.opponentCharImg?.active) {
   718→      this.opponentCharImg.setTexture(def.imageKey).setDisplaySize(58, 82);
   719→    } else if (this.opponentCharNameTxt?.active) {
   720→      // 아직 이미지가 없고 UI는 살아있음 → 새로 생성
   721→      this.opponentCharImg = this.add.image(304, 258, def.imageKey).setDisplaySize(58, 82);
   722→      this.uiGroup.push(this.opponentCharImg);
   723→    }
   724→    // 이름 / 등급
   725→    if (this.opponentCharNameTxt?.active) this.opponentCharNameTxt.setText(def.name).setColor('#ffffff');
   726→    if (this.opponentCharGradeTxt?.active) {
   727→      this.opponentCharGradeTxt.setText(def.grade).setColor(def.gradeColor);
   728→    }
   729→  }
   730→
   731→  // ─── 채널 이벤트 ───────────────────────────────────────────────
   732→
   733→  private setupChannelListeners() {
   734→    if (!this.battleChannel) return;
   735→
   736→    // Presence join — 호스트일 때 상대 입장 감지 → 준비완료 버튼 표시
   737→    // (readyButtonShown 가드로 중복 렌더링 방지)
   738→    this.battleChannel.onPresenceJoin(() => {
   739→      if (this.isHost) this.showReadyButton();
   740→    });
   741→
   742→    this.battleChannel.onPresenceLeave(() => {
   743→      this.opponentReady = false;
   744→      this.ui(this.add.text(200, 420, '⚠️ 상대방이 나갔습니다', {
   745→        fontSize: '16px', color: '#ff4444',
   746→        stroke: '#000', strokeThickness: 3,
   747→      }).setOrigin(0.5));
   748→    });
   749→
   750→    // READY 수신 = 상대 준비 완료 + 캐릭터 정보
   751→    this.battleChannel.onEvent(BattleEvent.READY, (payload: ReadyPayload) => {
   752→      this.opponentReady = true;
   753→      if (payload.userId) this.opponentUserId = payload.userId;
   754→      if (payload.characterId) {
   755→        this.opponentCharId = payload.characterId;
   756→        if (this.readyButtonShown) this.showOpponentCharacter(payload.characterId);
   757→      }
   758→      if (this.isHost) this.showReadyButton();
   759→      this.checkBothReady();
   760→    });
   761→
   762→    this.battleChannel.onEvent(BattleEvent.GAME_START, () => {
   763→      if (!this.countdownStarted) {
   764→        this.countdownStarted = true;
   765→        this.showCountdown();
   766→      }
   767→    });
   768→  }
   769→
   770→  /** ready 전송 (준비완료 버튼에서 호출) */
   771→  private doSendReady() {
   772→    if (!this.battleChannel || this.myReady) return;
   773→    this.myReady = true;
   774→    const charId = getSafeSelectedCharacter();
   775→    this.battleChannel.sendReady(charId);
   776→
   777→    // UI 갱신: 상대 대기 화면
   778→    this.clearUI();
   779→    this.ui(this.add.text(200, 270, '✅ 준비 완료!', {
   780→      fontSize: '24px', color: '#00ff00', fontStyle: 'bold',
   781→      stroke: '#000', strokeThickness: 4,
   782→    }).setOrigin(0.5));
   783→    this.ui(this.add.text(200, 320, '상대를 기다리는 중...', {
   784→      fontSize: '16px', color: '#ffffff',
   785→      stroke: '#000', strokeThickness: 3,
   786→    }).setOrigin(0.5));
   787→
   788→    // READY를 주기적으로 재전송 — 네트워크/타이밍 이슈로 상대가 수신 못했을 때 대비
   789→    // setInterval 사용 (Phaser 타이머는 백그라운드 탭에서 멈추므로)
   790→    this.clearReadyRetry();
   791→    this.readyRetryTimer = setInterval(() => {
   792→      if (this.countdownStarted || !this.battleChannel) {
   793→        this.clearReadyRetry();
   794→        return;
   795→      }
   796→      this.battleChannel.sendReady(charId);
   797→    }, 1500);
   798→
   799→    this.checkBothReady();
   800→  }
   801→
   802→  private clearReadyRetry() {
   803→    if (this.readyRetryTimer) {
   804→      clearInterval(this.readyRetryTimer);
   805→      this.readyRetryTimer = null;
   806→    }
   807→  }
   808→
   809→  private checkBothReady() {
   810→    if (this.myReady && this.opponentReady && this.isHost && !this.countdownStarted) {
   811→      this.countdownStarted = true;
   812→      this.battleChannel?.sendGameStart(Date.now());
   813→      this.showCountdown();
   814→    }
   815→  }
   816→
   817→  // ─── 상태 4: 카운트다운 ────────────────────────────────────────
   818→
   819→  private showCountdown() {
   820→    this.clearUI();
   821→
   822→    let count = 3;
   823→    const countText = this.ui(this.add.text(200, 280, `${count}`, {
   824→      fontSize: '90px', color: '#ff4444', fontStyle: 'bold',
   825→      stroke: '#000', strokeThickness: 8,
   826→    }).setOrigin(0.5));
   827→
   828→    const timer = this.time.addEvent({
   829→      delay: 1000,
   830→      callback: () => {
   831→        count--;
   832→        if (count > 0) {
   833→          (countText as Phaser.GameObjects.Text).setText(`${count}`);
   834→        } else {
   835→          (countText as Phaser.GameObjects.Text).setText('GO!');
   836→          (countText as Phaser.GameObjects.Text).setColor('#00ff00');
   837→          timer.remove();
   838→          this.time.delayedCall(500, () => this.goToBattle());
   839→        }
   840→      },
   841→      repeat: 2,
   842→    });
   843→  }
   844→
   845→  // ─── 씬 전환 ──────────────────────────────────────────────────
   846→
   847→  private goToBattle() {
   848→    this.clearReadyRetry();
   849→    const roomCode = this.battleChannel?.code ?? '';
   850→    const userId = this.userId;
   851→
   852→    // 동기식 채널 제거: supabase.channel()이 싱글턴이므로
   853→    // removeChannel을 먼저 호출해야 BattleGameScene에서 새 채널 생성 가능
   854→    if (this.battleChannel) {
   855→      this.battleChannel.destroyImmediate();
   856→      this.battleChannel = null;
   857→    }
   858→
   859→    this.scene.start('BattleGameScene', { roomCode, userId, opponentId: this.opponentUserId, isRanked: this.isRanked });
   860→  }
   861→
   862→  private removeInput() {
   863→    if (this.inputElement) {
   864→      this.inputElement.remove();
   865→      this.inputElement = null;
   866→    }
   867→  }
   868→
   869→  private async goBack() {
   870→    this.clearReadyRetry();
   871→    this.clearRankedPoll();
   872→    this.removeInput();
   873→    if (this.isMatchmaking) {
   874→      this.isMatchmaking = false;
   875→      cancelMatchmaking(this.userId).catch(() => {});
   876→    }
   877→    if (this.battleChannel) {
   878→      await this.battleChannel.destroy();
   879→      this.battleChannel = null;
   880→    }
   881→    this.scene.start('ModeSelectScene');
   882→  }
   883→
   884→  shutdown() {
   885→    this.clearReadyRetry();
   886→    this.clearRankedPoll();
   887→    this.removeInput();
   888→    if (this.isMatchmaking) {
   889→      this.isMatchmaking = false;
   890→      cancelMatchmaking(this.userId).catch(() => {});
   891→    }
   892→    if (this.battleChannel) {
   893→      this.battleChannel.destroyImmediate();
   894→      this.battleChannel = null;
   895→    }
   896→  }
   897→}
