    // 유저 ID: 재도전이면 전달받은 ID 사용, 아니면 비동기 조회
    if (this.autoRematch?.userId) {
      this.userId = this.autoRematch.userId;
    } else {
      this.userId = `anon-${Date.now()}`;
      supabase.auth.getUser().then(({ data }) => {
