private pickMenuCharacter(delta: number) {
  const now = Date.now();
  if (now - this.lastPickTime < 250) return;
  this.lastPickTime = now;
  this.charPickIdx = (this.charPickIdx + delta + this.ownedChars.length) % this.ownedChars.length;

