-- 기존 3-파라미터 버전 명시적 삭제 (파라미터 수가 달라 CREATE OR REPLACE 불가)
DROP FUNCTION IF EXISTS submit_battle_record(UUID, TEXT, INTEGER);

-- 친선전 전적 컬럼 추가
ALTER TABLE public.battle_records
  ADD COLUMN IF NOT EXISTS friendly_wins        INTEGER NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS friendly_losses      INTEGER NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS friendly_disconnects INTEGER NOT NULL DEFAULT 0;

-- submit_battle_record 함수 업데이트: p_is_ranked 파라미터 추가
CREATE OR REPLACE FUNCTION submit_battle_record(
  p_user_id     UUID,
  p_result      TEXT,
  p_point_delta INTEGER,
  p_is_ranked   BOOLEAN DEFAULT TRUE
)
RETURNS TABLE(
  rating_points        INTEGER,
  wins                 INTEGER,
  losses               INTEGER,
  disconnects          INTEGER,
  friendly_wins        INTEGER,
  friendly_losses      INTEGER,
  friendly_disconnects INTEGER,
  rank                 BIGINT
)
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  v_rp   INT;
  v_w    INT;
  v_l    INT;
  v_d    INT;
  v_fw   INT;
  v_fl   INT;
  v_fd   INT;
  v_rank BIGINT;
BEGIN
  INSERT INTO public.battle_records (user_id) VALUES (p_user_id)
  ON CONFLICT (user_id) DO NOTHING;

  IF p_is_ranked THEN
    UPDATE public.battle_records SET
      rating_points = GREATEST(0, rating_points + p_point_delta),
      wins        = wins        + CASE WHEN p_result = 'win'        THEN 1 ELSE 0 END,
      losses      = losses      + CASE WHEN p_result = 'lose'       THEN 1 ELSE 0 END,
      disconnects = disconnects + CASE WHEN p_result = 'disconnect' THEN 1 ELSE 0 END,
      updated_at  = NOW()
    WHERE user_id = p_user_id;
  ELSE
    UPDATE public.battle_records SET
      friendly_wins        = friendly_wins        + CASE WHEN p_result = 'win'        THEN 1 ELSE 0 END,
      friendly_losses      = friendly_losses      + CASE WHEN p_result = 'lose'       THEN 1 ELSE 0 END,
      friendly_disconnects = friendly_disconnects + CASE WHEN p_result = 'disconnect' THEN 1 ELSE 0 END,
      updated_at  = NOW()
    WHERE user_id = p_user_id;
  END IF;

  SELECT br.rating_points, br.wins, br.losses, br.disconnects,
         br.friendly_wins, br.friendly_losses, br.friendly_disconnects
    INTO v_rp, v_w, v_l, v_d, v_fw, v_fl, v_fd
    FROM public.battle_records br WHERE br.user_id = p_user_id;

  SELECT COUNT(*) + 1 INTO v_rank
    FROM public.battle_records WHERE rating_points > v_rp;

  RETURN QUERY SELECT
    COALESCE(v_rp, 0), COALESCE(v_w, 0), COALESCE(v_l, 0), COALESCE(v_d, 0),
    COALESCE(v_fw, 0), COALESCE(v_fl, 0), COALESCE(v_fd, 0), v_rank;
END; $$;

REVOKE ALL ON FUNCTION submit_battle_record FROM PUBLIC;
GRANT EXECUTE ON FUNCTION submit_battle_record TO service_role;

