   226→      this.tierText.setColor('#cccccc');
   227→    }
   228→
   229→    const deltaStr = res.pointDelta >= 0 ? `+${res.pointDelta} RP` : `${res.pointDelta} RP`;
   230→    this.rpDeltaText.setText(deltaStr);
   231→    this.rpDeltaText.setColor(res.pointDelta >= 0 ? '#00ff88' : '#ff4444');
   232→
