     3→export interface MatchResult {
     4→  status: 'waiting' | 'matched';
     5→  roomCode: string | null;
     6→  isHost: boolean | null;
     7→  opponentId: string | null;
     8→}
     9→
    10→type QueueRow = {
    11→  status: string;
    12→  room_code: string | null;
    13→  is_host: boolean | null;
    14→  opponent_id: string | null;
    15→};
    16→
    17→function rowToMatchResult(row: QueueRow): MatchResult {
    18→  return {
    19→    status: row.status as 'waiting' | 'matched',
    20→    roomCode: row.room_code,
    21→    isHost: row.is_host,
    22→    opponentId: row.opponent_id,
    23→  };
    24→}
    25→
    26→/** 인증된 userId 획득 (세션 없으면 익명 로그인 후 반환) */
    27→export async function getAuthUserId(): Promise<string> {
    28→  let { data: { session } } = await supabase.auth.getSession();
    29→  if (!session) {
    30→    const { data } = await supabase.auth.signInAnonymously();
    31→    session = data.session;
    32→  }
    33→  if (!session) throw new Error('Failed to authenticate for matchmaking');
    34→  return session.user.id;
    35→}
    36→
    37→/** 랭크 매치 참가 또는 즉시 매칭 시도 (원자적 RPC) */
    38→export async function findOrCreateMatch(userId: string): Promise<MatchResult> {
    39→  const { data, error } = await supabase.rpc('find_or_create_match', { p_user_id: userId });
    40→  if (error) throw error;
    41→  return rowToMatchResult((data as QueueRow[])[0]);
    42→}
    43→
    44→/** 매칭 상태 폴링 — 본인 row 조회 */
    45→export async function pollMatchStatus(userId: string): Promise<MatchResult | null> {
    46→  const { data } = await supabase
    47→    .from('matchmaking_queue')
    48→    .select('status, room_code, is_host, opponent_id')
    49→    .eq('user_id', userId)
    50→    .maybeSingle();
    51→  if (!data) return null;
    52→  return rowToMatchResult(data as QueueRow);
    53→}
    54→
    55→/** 매치메이킹 취소 — 대기열에서 본인 제거 */
    56→export async function cancelMatchmaking(userId: string): Promise<void> {
    57→  await supabase.from('matchmaking_queue').delete().eq('user_id', userId);
    58→}
