   212→  /** 제출 응답 수신 후 RP/티어 UI 업데이트 */
   213→  private showRpResult(res: SubmitBattleResultResponse) {
   214→    if (!this.tierText?.active || !this.rpDeltaText?.active) return;
   215→
   216→    const oldTierIdx = getTierIndex(res.previousRp);
   217→    const newTierIdx = getTierIndex(res.ratingPoints);
   218→    const newTier = getBattleTier(res.ratingPoints);
   219→
   220→    if (newTierIdx > oldTierIdx) {
   221→      const oldTier = getBattleTier(res.previousRp);
   222→      this.tierText.setText(`${oldTier.icon} ${oldTier.name}  →  ${newTier.icon} ${newTier.name}`);
   223→      this.tierText.setColor('#FFD700');
   224→    } else {
   225→      this.tierText.setText(`${newTier.icon} ${newTier.name}  |  ${res.ratingPoints} RP`);
   226→      this.tierText.setColor('#cccccc');
   227→    }
   228→
   229→    const deltaStr = res.pointDelta >= 0 ? `+${res.pointDelta} RP` : `${res.pointDelta} RP`;
   230→    this.rpDeltaText.setText(deltaStr);
   231→    this.rpDeltaText.setColor(res.pointDelta >= 0 ? '#00ff88' : '#ff4444');
   232→
   233→    if (this.currentRpText?.active) {
   234→      this.currentRpText.setText(`현재 ${res.ratingPoints} RP`);
   235→    }
   236→  }
   237→
   238→  // ─── 재도전 채널 ────────────────────────────────────────────────
   239→
   240→  private async initRematchChannel() {
   241→    this.rematchChannel = new BattleChannel();
   242→    this.rematchChannel.joinResult(this.roomCode, this.userId);
   243→
   244→    // subscribe 전에 리스너 등록
   245→    this.rematchChannel.onEvent(BattleEvent.REMATCH_REQUEST, () => {
   246→      this.onOpponentRematchRequest();
   247→    });
   248→
   249→    // RESULT_LEAVE: 상대가 의도적으로 내비게이션 시 즉시 알림 (Broadcast 기반)
   250→    this.rematchChannel.onEvent(BattleEvent.RESULT_LEAVE, () => {
   251→      this.onOpponentLeft();
   252→    });
   253→
   254→    // Presence leave: 브라우저 종료 등 예기치 않은 이탈 fallback
   255→    this.rematchChannel.onPresenceLeave(() => {
   256→      this.onOpponentLeft();
   257→    });
   258→
   259→    await this.rematchChannel.subscribe();
   260→  }
   261→
   262→  /** 재대전 버튼 클릭 */
   263→  private handleRematchClick() {
   264→    if (this.myRematchRequested || this.rematchTransitioning) return;
   265→    this.myRematchRequested = true;
   266→
   267→    // 버튼 → 대기 상태
   268→    this.rematchBtn.setFillStyle(0x555555);
   269→    this.rematchBtn.removeInteractive();
   270→    this.rematchBtnLabel.setText('⏳ 상대 대기 중...');
   271→
   272→    // 상대에게 재도전 의사 전송
   273→    if (this.rematchChannel) {
   274→      this.rematchChannel.sendRematchRequest();
   275→    }
   276→
   277→    // 상대도 이미 요청해놨으면 바로 전환
   278→    this.checkBothRematch();
   279→  }
   280→
   281→  /** 상대가 재도전 요청을 보냈을 때 */
   282→  private onOpponentRematchRequest() {
   283→    if (this.rematchTransitioning) return;
   284→    this.opponentRematchRequested = true;
   285→
   286→    // 내가 아직 안 눌렀다면 → 강조 알림
   287→    if (!this.myRematchRequested) {
   288→      if (this.rematchStatusText?.active) {
   289→        this.rematchStatusText.setText('⚔️ 상대가 재도전을 원합니다!');
   290→        this.rematchStatusText.setColor('#FFD700');
   291→      }
   292→      // 버튼 펄스 애니메이션
   293→      this.tweens.add({
   294→        targets: this.rematchBtn,
   295→        scaleX: 1.06,
   296→        scaleY: 1.06,
   297→        duration: 280,
   298→        yoyo: true,
   299→        repeat: -1,
   300→      });
   301→    }
   302→
   303→    this.checkBothRematch();
   304→  }
   305→
   306→  /** 상대가 채널에서 이탈했을 때 (RESULT_LEAVE broadcast + Presence leave 양쪽에서 호출될 수 있음) */
   307→  private onOpponentLeft() {
   308→    if (this.rematchTransitioning || this.opponentRematchRequested || this.opponentLeftHandled) return;
   309→    this.opponentLeftHandled = true;
   310→
   311→    if (this.rematchStatusText?.active) {
   312→      this.rematchStatusText.setText('😢 상대가 나갔습니다');
   313→      this.rematchStatusText.setColor('#ff6666');
   314→    }
   315→
   316→    // 재대전 버튼 비활성화
   317→    this.tweens.killTweensOf(this.rematchBtn);
   318→    this.rematchBtn.setFillStyle(0x333333);
   319→    this.rematchBtn.removeInteractive();
   320→    if (!this.myRematchRequested) {
   321→      this.rematchBtnLabel.setText('재도전 불가');
   322→    }
   323→  }
   324→
   325→  /** 양쪽 모두 재도전 의사 확인 시 BattleMatchScene으로 전환 */
   326→  private checkBothRematch() {
   327→    if (!this.myRematchRequested || !this.opponentRematchRequested) return;
   328→    if (this.rematchTransitioning) return;
   329→    this.rematchTransitioning = true;
   330→
   331→    this.tweens.killTweensOf(this.rematchBtn);
   332→
   333→    if (this.rematchStatusText?.active) {
   334→      this.rematchStatusText.setText('🔄 재대전 시작!');
   335→      this.rematchStatusText.setColor('#00ff88');
   336→    }
   337→
   338→    // 호스트 결정: userId 사전순 비교 (양쪽에서 동일하게 계산)
   339→    const isHost = this.userId < this.opponentId;
   340→
   341→    this.time.delayedCall(700, () => {
   342→      if (this.rematchChannel) {
   343→        this.rematchChannel.destroyImmediate();
   344→        this.rematchChannel = null;
   345→      }
   346→      this.scene.start('BattleMatchScene', {
   347→        autoRematch: { code: this.roomCode, isHost, userId: this.userId },
   348→      });
   349→    });
   350→  }
   351→
   352→  /**
   353→   * 재도전 외 내비게이션 시 상대에게 이탈 broadcast 전송 후 씬 전환
   354→   * Presence leave는 WebSocket 타임아웃에 의존하므로 신뢰성 낮음 →
   355→   * 의도적 이탈은 Broadcast로 즉시 알림
   356→   */
   357→  private navigateAway(targetScene: string) {
   358→    if (this.rematchChannel) {
   359→      this.rematchChannel.sendResultLeave();
   360→      this.rematchChannel.destroyImmediate();
   361→      this.rematchChannel = null;
   362→    }
   363→    this.scene.start(targetScene);
   364→  }
   365→
   366→  shutdown() {
   367→    if (this.rematchChannel) {
   368→      this.rematchChannel.destroyImmediate();
   369→      this.rematchChannel = null;
   370→    }
   371→  }
   372→}
