   743→  private setupChannelListeners() {
   744→    if (!this.battleChannel) return;
   745→
   746→    // Presence join — 상대 입장 감지 → 내 캐릭터 재알림 + 호스트는 준비 버튼 표시
   747→    this.battleChannel.onPresenceJoin(() => {
   748→      // 늦게 접속한 상대가 내 캐릭터를 모를 수 있으므로 재전송
   749→      this.battleChannel?.sendCharAnnounce(getSafeSelectedCharacter());
   750→      if (this.isHost) this.showReadyButton();
   751→    });
   752→
   753→    this.battleChannel.onPresenceLeave(() => {
   754→      this.opponentReady = false;
   755→      this.ui(this.add.text(200, 420, '⚠️ 상대방이 나갔습니다', {
   756→        fontSize: '16px', color: '#ff4444',
   757→        stroke: '#000', strokeThickness: 3,
   758→      }).setOrigin(0.5));
   759→    });
   760→
   761→    // CHAR_ANNOUNCE: 채널 연결 직후 상대 캐릭터 자동 수신
   762→    this.battleChannel.onEvent(BattleEvent.CHAR_ANNOUNCE, (payload) => {
   763→      if (payload.characterId && payload.characterId !== this.opponentCharId) {
   764→        this.opponentCharId = payload.characterId;
   765→        if (this.readyButtonShown) this.showOpponentCharacter(payload.characterId);
   766→      }
   767→    });
   768→
   769→    // READY 수신 = 상대 준비 완료 + 캐릭터 정보
   770→    this.battleChannel.onEvent(BattleEvent.READY, (payload: ReadyPayload) => {
   771→      this.opponentReady = true;
   772→      if (payload.userId) this.opponentUserId = payload.userId;
   773→      if (payload.characterId) {
   774→        this.opponentCharId = payload.characterId;
   775→        if (this.readyButtonShown) this.showOpponentCharacter(payload.characterId);
   776→      }
   777→      if (this.isHost) this.showReadyButton();
   778→      this.checkBothReady();
   779→    });
   780→
   781→    this.battleChannel.onEvent(BattleEvent.GAME_START, () => {
   782→      if (!this.countdownStarted) {
   783→        this.countdownStarted = true;
   784→        this.showCountdown();
   785→      }
   786→    });
   787→  }
