   866→  private goToBattle() {
   867→    this.clearReadyRetry();
   868→    const roomCode = this.battleChannel?.code ?? '';
   869→    const userId = this.userId;
   870→
   871→    // 동기식 채널 제거: supabase.channel()이 싱글턴이므로
   872→    // removeChannel을 먼저 호출해야 BattleGameScene에서 새 채널 생성 가능
   873→    if (this.battleChannel) {
   874→      this.battleChannel.destroyImmediate();
   875→      this.battleChannel = null;
