   903→  shutdown() {
   904→    this.clearReadyRetry();
   905→    this.clearRankedPoll();
   906→    this.removeInput();
   907→    if (this.isMatchmaking) {
   908→      this.isMatchmaking = false;
   909→      cancelMatchmaking(this.userId).catch(() => {});
   910→    }
   911→    if (this.battleChannel) {
   912→      this.battleChannel.destroyImmediate();
   913→      this.battleChannel = null;
   914→    }
   915→  }
