     1→import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
     2→
     3→const corsHeaders = {
     4→  'Access-Control-Allow-Origin': '*',
     5→  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
     6→};
     7→
     8→const TIER_NAMES = ['알파', '베타', '레거시', '마스터', '갓'];
     9→const TIER_ICONS = ['🔴', '🟠', '🟡', '💎', '👑'];
    10→const TIER_MINS  = [0, 500, 1000, 1500, 2000];
    11→
    12→function getTierIndex(rp: number): number {
    13→  for (let i = TIER_MINS.length - 1; i >= 0; i--) {
    14→    if (rp >= TIER_MINS[i]) return i;
    15→  }
    16→  return 0;
    17→}
    18→
    19→Deno.serve(async (req: Request) => {
    20→  if (req.method === 'OPTIONS') {
    21→    return new Response('ok', { headers: corsHeaders });
    22→  }
    23→
    24→  try {
    25→    const { limit: limitParam } = await req.json().catch(() => ({}));
    26→    const safeLimit = Math.min(Math.max(1, parseInt(limitParam ?? '20', 10)), 100);
    27→
    28→    // JWT에서 사용자 인증 (선택적 — 비로그인 시에도 랭킹 조회 가능)
    29→    const authHeader = req.headers.get('Authorization');
    30→    let currentUserId: string | null = null;
    31→
    32→    if (authHeader) {
    33→      const supabaseUser = createClient(
    34→        Deno.env.get('SUPABASE_URL') ?? '',
    35→        Deno.env.get('SUPABASE_ANON_KEY') ?? '',
    36→        { global: { headers: { Authorization: authHeader } } },
    37→      );
    38→      const { data: { user } } = await supabaseUser.auth.getUser();
    39→      currentUserId = user?.id ?? null;
    40→    }
    41→
    42→    const supabaseAdmin = createClient(
    43→      Deno.env.get('SUPABASE_URL') ?? '',
    44→      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '',
    45→    );
    46→
    47→    // 랭킹 뷰 조회 (rating_points DESC 정렬)
    48→    const { data: leaderboard, error: leaderboardError } = await supabaseAdmin
    49→      .from('battle_leaderboard_view')
    50→      .select('user_id, rating_points, wins, losses, disconnects, win_rate, initials')
    51→      .limit(safeLimit);
    52→
    53→    if (leaderboardError) {
    54→      console.error('Leaderboard query error:', leaderboardError);
    55→      return new Response(
    56→        JSON.stringify({ error: 'Failed to fetch leaderboard' }),
    57→        { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
    58→      );
    59→    }
    60→
    61→    const entries = (leaderboard ?? []).map((entry, index) => {
    62→      const rp: number = (entry.rating_points as number) ?? 0;
    63→      const tierIdx = getTierIndex(rp);
    64→      return {
    65→        rank: index + 1,
    66→        userId: entry.user_id,
    67→        userName: (entry.initials as string | null) ?? '???',
    68→        wins: entry.wins,
    69→        losses: entry.losses,
    70→        disconnects: entry.disconnects,
    71→        totalWins: (entry.wins as number) + (entry.disconnects as number),
    72→        winRate: Number(entry.win_rate),
    73→        ratingPoints: rp,
    74→        tierName: TIER_NAMES[tierIdx],
    75→        tierIcon: TIER_ICONS[tierIdx],
    76→      };
    77→    });
    78→
    79→    // 현재 유저 순위 조회
    80→    // 이미 상위 N명 뷰에 있으면 추가 쿼리 없이 entries에서 바로 계산
    81→    let currentUserRank: {
    82→      rank: number;
    83→      totalWins: number;
    84→      winRate: number;
    85→      ratingPoints: number;
    86→      friendlyWins: number;
    87→      friendlyLosses: number;
    88→      friendlyDisconnects: number;
    89→    } | null = null;
    90→
    91→    if (currentUserId) {
    92→      // 항상 battle_records 단건 조회 (친선전 컬럼 포함)
    93→      const { data: userRecord } = await supabaseAdmin
    94→        .from('battle_records')
    95→        .select('wins, losses, disconnects, rating_points, friendly_wins, friendly_losses, friendly_disconnects')
    96→        .eq('user_id', currentUserId)
    97→        .maybeSingle();
    98→
    99→      if (userRecord) {
   100→        const rp: number = (userRecord as { rating_points: number }).rating_points ?? 0;
   101→        const totalWins = (userRecord.wins as number) + (userRecord.disconnects as number);
   102→        const myInTop = entries.find(e => e.userId === currentUserId);
   103→        let rank: number;
   104→
   105→        if (myInTop) {
   106→          rank = myInTop.rank;
   107→        } else {
   108→          const { data: rankResult } = await supabaseAdmin
   109→            .rpc('get_battle_rank_by_rp', { p_rp: rp });
   110→          rank = Number(rankResult ?? 0) + 1;
   111→        }
   112→
   113→        const totalGames =
   114→          (userRecord.wins as number) +
   115→          (userRecord.losses as number) +
   116→          (userRecord.disconnects as number);
   117→        const winRate = totalGames === 0
   118→          ? 0
   119→          : Math.round(totalWins / totalGames * 1000) / 10;
   120→
   121→        currentUserRank = {
   122→          rank,
   123→          totalWins,
   124→          winRate,
   125→          ratingPoints: rp,
   126→          friendlyWins: (userRecord.friendly_wins as number) ?? 0,
   127→          friendlyLosses: (userRecord.friendly_losses as number) ?? 0,
   128→          friendlyDisconnects: (userRecord.friendly_disconnects as number) ?? 0,
   129→        };
   130→      }
   131→    }
   132→
   133→    return new Response(
   134→      JSON.stringify({
   135→        success: true,
   136→        leaderboard: entries,
   137→        currentUserRank,
   138→      }),
   139→      { headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
   140→    );
   141→  } catch (error) {
   142→    console.error('Unexpected error:', error);
   143→    return new Response(
   144→      JSON.stringify({ error: 'Internal server error' }),
   145→      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
   146→    );
   147→  }
   148→});
