   291→  private async startRankedMatchmaking() {
   292→    if (this.isMatchmaking || this.battleChannel) return;
   293→    this.isMatchmaking = true;
   294→
   295→    try {
   296→      // 인증 보장 (익명 로그인 포함)
   297→      this.userId = await getAuthUserId();
   298→    } catch {
   299→      this.isMatchmaking = false;
   300→      return;
   301→    }
   302→
   303→    this.showRankedWaiting();
   304→
   305→    let result: MatchResult;
   306→    try {
   307→      result = await findOrCreateMatch(this.userId);
   308→    } catch {
   309→      this.isMatchmaking = false;
   310→      this.showMenu();
   311→      return;
   312→    }
   313→
   314→    if (result.status === 'matched') {
   315→      this.onRankedMatchFound(result);
   316→      return;
   317→    }
   318→
   319→    // 대기 중 — 2초마다 폴링
   320→    this.rankMatchPollTimer = setInterval(async () => {
   321→      try {
   322→        const poll = await pollMatchStatus(this.userId);
   323→        if (poll?.status === 'matched') {
   324→          this.clearRankedPoll();
   325→          this.onRankedMatchFound(poll);
   326→        }
   327→      } catch {
   328→        // 네트워크 오류 시 계속 재시도
   329→      }
   330→    }, 2000);
   331→  }
