   633→
   634→    this.ui(this.add.text(200, 180, '상대방과 연결되었습니다!', {
   635→      fontSize: '18px', color: '#00ff88', fontStyle: 'bold',
   636→      stroke: '#000', strokeThickness: 3,
   637→    }).setOrigin(0.5));
   638→
   639→    // ── VS 레이블 ─────────────────────────────────────────────────
   640→    this.ui(this.add.text(96, 215, '나', {
   641→      fontSize: '15px', color: '#aaaaaa', stroke: '#000', strokeThickness: 3,
   642→    }).setOrigin(0.5));
   643→    this.ui(this.add.text(200, 213, 'VS', {
   644→      fontSize: '22px', color: '#ff4444', fontStyle: 'bold',
   645→      stroke: '#000', strokeThickness: 5,
   646→    }).setOrigin(0.5));
   647→    this.ui(this.add.text(304, 215, '상대', {
   648→      fontSize: '15px', color: '#aaaaaa', stroke: '#000', strokeThickness: 3,
   649→    }).setOrigin(0.5));
   650→
   651→    // ── 내 캐릭터 (왼쪽) ─────────────────────────────────────────
   652→    this.ui(this.add.rectangle(96, 280, 92, 104, 0x000033, 0.7)
   653→      .setStrokeStyle(2, 0x4466ff));
   654→    if (this.textures.exists(myDef.imageKey)) {
