   663→    }).setOrigin(0.5));
   664→
   665→    // ── 상대 캐릭터 (오른쪽) ─────────────────────────────────────
   666→    this.ui(this.add.rectangle(304, 280, 92, 104, 0x330000, 0.7)
   667→      .setStrokeStyle(2, 0xff4444));
   668→
   669→    // 항상 플레이스홀더 먼저 생성 — updateOpponentCharDisplay가 이 객체를 기준으로 업데이트
   670→    this.opponentCharPlaceholder = this.ui(this.add.text(304, 280, '?', {
   671→      fontSize: '42px', color: '#555555', stroke: '#000', strokeThickness: 3,
   672→    }).setOrigin(0.5));
   673→    this.opponentCharNameTxt = this.ui(this.add.text(304, 342, '대기 중...', {
   674→      fontSize: '14px', color: '#666666', stroke: '#000', strokeThickness: 2,
   675→    }).setOrigin(0.5));
   676→    this.opponentCharGradeTxt = this.ui(this.add.text(304, 362, '', {
   677→      fontSize: '13px', color: '#666666',
   678→    }).setOrigin(0.5));
   679→
   680→    // 이미 캐릭터를 알고 있으면 즉시 표시
