   743→  private setupChannelListeners() {
   744→    if (!this.battleChannel) return;
   745→
   746→    // Presence join — 상대 입장 감지 → 내 캐릭터 재알림 + 호스트는 준비 버튼 표시
   747→    this.battleChannel.onPresenceJoin(() => {
