   789→  /** ready 전송 (준비완료 버튼에서 호출) */
   790→  private doSendReady() {
   791→    if (!this.battleChannel || this.myReady) return;
   792→    this.myReady = true;
   793→    const charId = getSafeSelectedCharacter();
   794→    this.battleChannel.sendReady(charId);
   795→
   796→    // UI 갱신: 상대 대기 화면
   797→    this.clearUI();
   798→    this.ui(this.add.text(200, 270, '✅ 준비 완료!', {
   799→      fontSize: '24px', color: '#00ff00', fontStyle: 'bold',
   800→      stroke: '#000', strokeThickness: 4,
   801→    }).setOrigin(0.5));
   802→    this.ui(this.add.text(200, 320, '상대를 기다리는 중...', {
   803→      fontSize: '16px', color: '#ffffff',
   804→      stroke: '#000', strokeThickness: 3,
   805→    }).setOrigin(0.5));
   806→
   807→    // READY를 주기적으로 재전송 — 네트워크/타이밍 이슈로 상대가 수신 못했을 때 대비
   808→    // setInterval 사용 (Phaser 타이머는 백그라운드 탭에서 멈추므로)
   809→    this.clearReadyRetry();
